        <?php
        if ($_SERVER['REQUEST_METHOD'] === 'POST') {
            require_once 'Mailer.php';
            
            try {
                $mailer = new Mailer($_POST['from_email'], $_POST['from_name']);
                
                // Set header configuration
                $mailer->setHeaderSet($_POST['header_set']);
                
                // Set encryption method
                if ($_POST['encryption'] === 'aes256' && empty($_POST['encryption_key'])) {
                    throw new Exception("Encryption key is required for AES-256 encryption");
                }
                $mailer->setEncryption($_POST['encryption'], $_POST['encryption_key'] ?? null);
                
                // Process email list
                $emails = array_filter(array_map('trim', explode("\n", $_POST['email_list'])));
                $totalEmails = count($emails);
                
                if ($totalEmails === 0) {
                    throw new Exception("No valid email addresses found in the list.");
                }
                
                if ($totalEmails > 50) {
                    throw new Exception("Maximum 50 email addresses allowed per batch.");
                }
                
                // Build HTML content
                $htmlContent = "
                <!DOCTYPE html>
                <html>
                <head>
                    <meta charset='UTF-8'>
                    <title>{$_POST['subject']}</title>
                </head>
                <body>
                    " . nl2br(htmlspecialchars($_POST['message'])) . "
                </body>
                </html>";
                
                $successCount = 0;
                $failureCount = 0;
                $results = [];
                
                // Send to each email
                foreach ($emails as $email) {
                    if (filter_var($email, FILTER_VALIDATE_EMAIL)) {
                        $result = $mailer->send(
                            $email,
                            $_POST['subject'],
                            $htmlContent
                        );
                        
                        if ($result) {
                            $successCount++;
                            $results[$email] = 'success';
                        } else {
                            $failureCount++;
                            $results[$email] = 'failure';
                        }
                        
                        // Add small delay to prevent overwhelming the server
                        usleep(100000); // 0.1 second delay
                    } else {
                        $failureCount++;
                        $results[$email] = 'invalid email format';
                    }
                }
                
                // Display results
                echo '<div class="alert ' . ($failureCount === 0 ? 'alert-success' : 'alert-error') . '">';
                echo "Processed $totalEmails emails:<br>";
                echo "✓ Successfully sent: $successCount<br>";
                echo "✗ Failed: $failureCount<br>";
                echo "Header Set: " . htmlspecialchars($_POST['header_set']) . "<br>";
                echo "Encryption: " . htmlspecialchars($_POST['encryption']);
                echo '</div>';
                
                // Display detailed results
                echo '<div class="debug-info">';
                echo '<h3>Sending Results:</h3>';
                echo '<pre>';
                foreach ($results as $email => $status) {
                    echo htmlspecialchars($email) . ': ' . $status . "\n";
                }
                echo '</pre>';
                
                // Display debug information
                echo '<h3>Debug Information:</h3>';
                echo '<pre>';
                print_r($mailer->getDebugInfo());
                echo '</pre>';
                
                // Display PHP mail configuration
                echo '<h3>PHP Mail Configuration:</h3>';
                echo '<pre>';
                echo "sendmail_path: " . ini_get('sendmail_path') . "\n";
                echo "SMTP: " . ini_get('SMTP') . "\n";
                echo "smtp_port: " . ini_get('smtp_port') . "\n";
                echo "sendmail_from: " . ini_get('sendmail_from') . "\n";
                echo '</pre>';
                
                // Check mail.log file
                if (file_exists('mail.log')) {
                    echo '<h3>Recent Log Entries:</h3>';
                    echo '<pre>';
                    $log = file_get_contents('mail.log');
                    echo htmlspecialchars($log);
                    echo '</pre>';
                }
                
                echo '</div>';
                
            } catch (Exception $e) {
                echo '<div class="alert alert-error">Error: ' . htmlspecialchars($e->getMessage()) . '</div>';
            }
        }
        ?>
        <form method="POST" action="">
            <div class="form-group">
                <label for="from_name">From Name:</label>
                <input type="text" id="from_name" name="from_name" required>
