                <div class="email-count" id="emailCount">0 emails entered</div>
            </div>
            
            <div class="form-group">
                <label for="header_set">Header Set:</label>
                <select id="header_set" name="header_set" required>
                    <option value="minimal">Minimal - Basic headers only</option>
                    <option value="standard" selected>Standard - Common headers</option>
                    <option value="enhanced">Enhanced - Additional tracking & priority</option>
                    <option value="stealth">Stealth - Randomized headers</option>
                </select>
            </div>
            
            <div class="form-group">
                <label for="encryption">Encryption Method:</label>
                <select id="encryption" name="encryption" required>
                    <option value="none">None - No encryption</option>
                    <option value="base64" selected>Base64 - Standard encoding</option>
                    <option value="quoted-printable">Quoted Printable - RFC 2045</option>
                    <option value="aes256">AES-256 - Strong encryption</option>
                </select>
            </div>
            
            <div id="encryption_key_group" class="form-group" style="display: none;">
                <label for="encryption_key">Encryption Key:</label>
                <input type="password" id="encryption_key" name="encryption_key" placeholder="Required for AES-256 encryption">
            </div>
            
            <div class="form-group">
                <label for="subject">Subject:</label>
                <input type="text" id="subject" name="subject" required>
            </div>
            
            <div class="form-group">
                <label for="message">Message:</label>
                <textarea id="message" name="message" required></textarea>
            </div>
            
            <button type="submit">Send Emails</button>
        </form>
