    <script>
    document.getElementById('email_list').addEventListener('input', function() {
        const emails = this.value.split('\n').filter(email => email.trim() !== '').length;
        document.getElementById('emailCount').textContent = emails + ' emails entered';
        if (emails > 50) {
            document.getElementById('emailCount').style.color = '#a94442';
        } else {
            document.getElementById('emailCount').style.color = '#666';
        }
    });
    
    document.getElementById('encryption').addEventListener('change', function() {
        const keyGroup = document.getElementById('encryption_key_group');
        if (this.value === 'aes256') {
            keyGroup.style.display = 'block';
            document.getElementById('encryption_key').required = true;
        } else {
            keyGroup.style.display = 'none';
            document.getElementById('encryption_key').required = false;
        }
    });
    
    // Trigger the count on page load
    document.getElementById('email_list').dispatchEvent(new Event('input'));
    </script>
</body>
</html> 